320			w, _ := doRequest(t, h, method, sessionChangesPath("sess", "doc1"))
321			if w.Code != http.StatusBadRequest {
322				t.Fatalf("%s status = %d, want 400, body = %q", method, w.Code, w.Body.String())
323			}
324			assertJSONError(t, w)
325		}
326	
327		// Empty identifiers, a trailing slash and extra segments are a JSON 400,
328		// never a redirect or an HTML page.
329		for _, p := range []string{
330			"/v1/sessions//documents/doc1/changes",
331			"/v1/sessions/sess/documents//changes",
332			"/v1/sessions/sess/documents/doc1/changes/",
333			"/v1/sessions/sess/documents/doc1/changes/extra",
334			"/v1/sessions/sess/documents/doc1/changes/extra/more",
335		} {
336			r := newJSONRequest(http.MethodPost, p, `{"changes":[{"id":"a","payload":1}]}`, "application/json")
337			w := serveRecorder(h, r)
338			if w.Code != http.StatusBadRequest {
339				t.Fatalf("POST %s status = %d, want 400, body = %q", p, w.Code, w.Body.String())
340			}
341			assertJSONError(t, w)
342			if loc := w.Header().Get("Location"); loc != "" {
343				t.Fatalf("POST %s redirected to %q", p, loc)
344			}
345			if strings.Contains(strings.ToLower(w.Body.String()), "<html") {
346				t.Fatalf("POST %s leaked HTML: %q", p, w.Body.String())
347			}
348		}
349	
350		// Zero writes: the document is still unknown.
351		rows, next, _ := s.ListChanges("doc1", 0, 100)
352		if len(rows) != 0 || next != 0 {
353			t.Fatalf("zero-write violated: rows = %v next = %d", rows, next)
354		}
355	}
