420		h, _ := newTestHandler(t)
421		createSessionViaHTTP(t, h, "dev", "sess")
422	
423		const n = 40
424		var wg sync.WaitGroup
425		errs := make(chan error, n)
426		for i := 0; i < n; i++ {
427			wg.Add(1)
428			go func(i int) {
