38	func TestPollUnknownDocumentImmediateEmpty(t *testing.T) {
39		h, _ := newTestHandler(t)
40	
41		done := make(chan struct {
42			code int
43			body map[string]any
44		}, 1)
45		go func() {
46			w, body := pollPage(t, h, "/v1/documents/ghost/changes/poll?waitMs=30000")
47			done <- struct {
48				code int
49				body map[string]any
50			}{w.Code, body}
51		}()
52		select {
53		case r := <-done:
54			if r.code != 200 {
55				t.Fatalf("status = %d", r.code)
56			}
57			if len(r.body["changes"].([]any)) != 0 || r.body["nextCursor"].(float64) != 0 || r.body["timedOut"] != false {
58				t.Fatalf("unknown doc page = %v", r.body)
59			}
60		case <-time.After(2 * time.Second):
61			t.Fatal("unknown document parked the poll")
62		}
63	}
64	
65	func TestPollTimeoutEchoesCursor(t *testing.T) {
66		h, _ := newTestHandler(t)
67		seedDoc(t, h, "doc", 2)
68	
69		start := time.Now()
70		w, body := pollPage(t, h, "/v1/documents/doc/changes/poll?after=2&waitMs=80")
71		elapsed := time.Since(start)
72		if w.Code != 200 {
73			t.Fatalf("status = %d body = %s", w.Code, w.Body.String())
74		}
75		if elapsed < 60*time.Millisecond {
76			t.Fatalf("poll returned after %v, wait did not elapse", elapsed)
77		}
78		if len(body["changes"].([]any)) != 0 || body["nextCursor"].(float64) != 2 || body["timedOut"] != true {
79			t.Fatalf("timeout page = %v", body)
80		}
81	}
