83	func TestPollRejectsBadParams(t *testing.T) {
84		h, _ := newTestHandler(t)
85		seedDoc(t, h, "doc", 1)
86		bad := []string{
87			"/v1/documents/doc/changes/poll?waitMs=-1",
88			"/v1/documents/doc/changes/poll?waitMs=30001",
89			"/v1/documents/doc/changes/poll?waitMs=abc",
90			"/v1/documents/doc/changes/poll?waitMs=1.5",
91			"/v1/documents/doc/changes/poll?after=-1&waitMs=10",
92			"/v1/documents/doc/changes/poll?after=x",
93			"/v1/documents/doc/changes/poll?limit=0",
94			"/v1/documents/doc/changes/poll?limit=1001",
95		}
96		for _, url := range bad {
97			w, body := doRequest(t, h, http.MethodGet, url)
98			if w.Code != http.StatusBadRequest {
99				t.Fatalf("%s status = %d, want 400", url, w.Code)
100			}
