107	// TestPollWakesOnCommit exercises a real listener: one client parks with a
108	// long wait, another request commits the first new change, and the parked
109	// client receives the page promptly with timedOut=false.
110	func TestPollWakesOnCommit(t *testing.T) {
111		h, _ := newTestHandler(t)
112		srv := httptest.NewServer(h)
