137		// Wait until the poll is parked, then commit from a second client.
138		time.Sleep(100 * time.Millisecond)
139		postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
140			"deviceId": "dev",
141			"changes":  []any{map[string]any{"id": "c2", "payload": map[string]any{"n": 2}}},
142		})
143	
144		select {
145		case r := <-got:
146			if r.err != nil {
147				t.Fatalf("poll request: %v", r.err)
148			}
149			if r.status != 200 {
150				t.Fatalf("status = %d body = %v", r.status, r.body)
151			}
152			rows := r.body["changes"].([]any)
153			if len(rows) != 1 || rows[0].(map[string]any)["id"] != "c2" {
154				t.Fatalf("woken rows = %v", rows)
