156			if r.body["nextCursor"].(float64) != 2 || r.body["timedOut"] != false {
157				t.Fatalf("woken page = %v", r.body)
158			}
159		case <-time.After(3 * time.Second):
160			t.Fatal("parked poll was not woken by the commit")
161		}
