164	// TestPollClientDisconnectWritesNothing verifies a disconnect ends the wait
165	// and a later poll sees the same cursor: waiting never persists anything.
166	func TestPollClientDisconnectWritesNothing(t *testing.T) {
167		h, s := newTestHandler(t)
168		srv := httptest.NewServer(h)
169		defer srv.Close()
170		seedDoc(t, h, "doc", 1)
171	
172		client := &http.Client{Timeout: 100 * time.Millisecond}
173		_, err := client.Get(srv.URL + "/v1/documents/doc/changes/poll?after=1&waitMs=30000")
174		if err == nil {
175			t.Fatal("expected the short client timeout to abort the request")
176		}
177	
178		// Give the server a moment to observe the disconnect, then confirm no
179		// state changed.
180		deadline := time.Now().Add(2 * time.Second)
181		for time.Now().Before(deadline) {
182			rows, next, lerr := s.ListChanges("doc", 0, 100)
183			if lerr != nil {
184				t.Fatal(lerr)
185			}
186			if len(rows) == 1 && next == 1 {
187				return
188			}
189			time.Sleep(20 * time.Millisecond)
190		}
191		t.Fatal("canceled wait appears to have written state")
192	}
