470	func TestReplayConcurrentWithPosts(t *testing.T) {
471		h, _ := newTestHandler(t)
472		// Devices used by every goroutine must be registered first.
473		register := func(id string) {
474			w, _ := postJSON(t, h, "/v1/devices", map[string]string{"deviceId": id})
475			if w.Code != 200 {
476				t.Fatalf("register %s: %d %s", id, w.Code, w.Body.String())
477			}
478		}
479		register("dev")
480		register("dev2")
481	
482		const n = 20
483		var wg sync.WaitGroup
484		errs := make(chan error, 2*n)
485		for i := 0; i < n; i++ {
486			wg.Add(2)
487			go func(i int) {
488				defer wg.Done()
489				w, _ := postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
490					"deviceId": "dev",
491					"changes":  []any{map[string]any{"id": fmt.Sprintf("post-%02d", i), "payload": map[string]any{"i": i}}},
492				})
493				if w.Code != 200 {
494					errs <- fmt.Errorf("post %d: %d %s", i, w.Code, w.Body.String())
495				}
496			}(i)
497			go func(i int) {
498				defer wg.Done()
499				w, _ := postJSON(t, h, "/v1/documents/doc/replay", map[string]any{
500					"deviceId":   "dev2",
501					"operations": []any{map[string]any{"id": fmt.Sprintf("replay-%02d", i), "payload": map[string]any{"i": i}}},
502				})
503				if w.Code != 200 {
504					errs <- fmt.Errorf("replay %d: %d %s", i, w.Code, w.Body.String())
505				}
506			}(i)
507		}
508		wg.Wait()
509		close(errs)
510		for err := range errs {
511			t.Error(err)
512		}
513	
514		w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes?limit=1000")
515		if w.Code != 200 {
516			t.Fatal(w.Body.String())
517		}
518		if got := len(body["changes"].([]any)); got != 2*n {
519			t.Fatalf("stored %d changes, want %d", got, 2*n)
520		}
521		if body["nextCursor"].(float64) != float64(2*n) {
522			t.Fatalf("nextCursor = %v, want %d", body["nextCursor"], 2*n)
523		}
524	}
